from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from silk.models import Request as SilkRequest

class UserProfilingActivityLogView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, account_id):
        # Prevent cross-user activity profiling
        if int(account_id) != request.user.id and not request.user.is_staff:
            return Response({"error": "Access denied"}, status=status.HTTP_403_FORBIDDEN)

        traces = SilkRequest.objects.filter(user_id=request.user.id).order_by("-start_time")[:15].values(
            "id", "path", "num_queries", "time_taken", "start_time"
        )
        return Response({"user_id": request.user.id, "activity_traces": list(traces)}, status=status.HTTP_200_OK)
